import bisect
def bucket_by_range(nums, boundaries):
    d = {}
    for x in nums:
        b = bisect.bisect_right(boundaries, x)
        d[b] = d.get(b, 0) + 1
    return d

def integer_cube_root(n):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def mask_phone_with_ext(phone_ext):
    if " x" in phone_ext:
        main, ext = phone_ext.split(" x", 1)
        ext_part = " x" + ext
    else:
        main, ext_part = phone_ext, ""
    digits_only = main.replace("-", "")
    last4 = digits_only[-4:]
    masked_main = "*" * (len(digits_only) - 4) + last4
    result_chars = []
    di = 0
    for c in main:
        if c == "-":
            result_chars.append("-")
        else:
            result_chars.append(masked_main[di])
            di += 1
    return "".join(result_chars) + ext_part

