def longest_palindromic_substring(s):
    if not s:
        return ""
    best = s[0]
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return s[l+1:r]
    for i in range(len(s)):
        odd = expand(i, i)
        if len(odd) > len(best):
            best = odd
        even = expand(i, i+1)
        if len(even) > len(best):
            best = even
    return best

def is_valid_utc_offset(s):
    import re
    m = re.fullmatch(r'([+-])(\d{2}):(\d{2})', s)
    if not m:
        return False
    sign, hh, mm = m.groups()
    if int(mm) > 59:
        return False
    total = int(hh) * 60 + int(mm)
    if sign == '-':
        total = -total
    return -12 * 60 <= total <= 14 * 60

def previous_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    candidate = n - 1
    while candidate >= 2 and not isp(candidate):
        candidate -= 1
    return candidate

