def normalize_ranks_dense(scores):
    distinct = sorted(set(scores))
    m = len(distinct)
    if m <= 1:
        return [0.0 for _ in scores]
    dense = {v: i for i, v in enumerate(distinct)}
    return [round(dense[v] / (m - 1), 4) for v in scores]

