def split_on_multiple_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for c in s:
        if c in delim_set:
            if current:
                tokens.append("".join(current))
                current = []
        else:
            current.append(c)
    if current:
        tokens.append("".join(current))
    return tokens

def normalize_slash_date(s):
