def is_valid_serial_checksum(s):
    alphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if len(s) != 8 or not all(c in alphabet for c in s):
        return False
    if not s[7].isdigit():
        return False
    total = sum(alphabet.index(c) for c in s[:7])
    return str(total % 10) == s[7]

def sort_words_by_unique_letter_ratio(words):
    def ratio(w):
        return len(set(w)) / len(w)
    return sorted(words, key=lambda w: (ratio(w), w))

